css:
@page {
    size: A4;
    margin: 15mm;
}

.receipt {
    font-family: Arial, sans-serif;
    padding: 15px;
}

.studio-name,
.studio-address,
.receipt-title,
.footer {
    text-align: center;
}

.studio-name {
    margin-bottom: 5px;
}

.receipt-title {
    margin: 25px 0;
}

.details {
    width: 100%;
    border-collapse: collapse;
}

.details td {
    padding: 10px;
    border-bottom: 1px solid #ddd;
}

.payment-box {
    margin-top: 25px;
    padding: 15px;
    font-size: 18px;
    text-align: right;
}
